import sys
from collections import deque

def solve():
    input = sys.stdin.read
    data = input().split()
    H, W = int(data[0]), int(data[1])
    grid = data[2:]

    # Direction vectors
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Mark cells that are adjacent to magnets
    blocked = [[False] * W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                for dx, dy in dirs:
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < H and 0 <= nj < W:
                        blocked[ni][nj] = True

    visited = [[False] * W for _ in range(H)]
    max_freedom = 0

    for si in range(H):
        for sj in range(W):
            if grid[si][sj] == '.' and not visited[si][sj]:
                # BFS from this cell
                q = deque()
                q.append((si, sj))
                visited[si][sj] = True
                reachable = set()
                reachable.add((si, sj))

                while q:
                    ci, cj = q.popleft()
                    if blocked[ci][cj]:
                        continue
                    for dx, dy in dirs:
                        ni, nj = ci + dx, cj + dy
                        if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '.':
                            reachable.add((ni, nj))
                            if not visited[ni][nj]:
                                visited[ni][nj] = True
                                q.append((ni, nj))

                max_freedom = max(max_freedom, len(reachable))

    print(max_freedom)

if __name__ == "__main__":
    solve()
```

