def last_non_empty_string(s: str) -> str:
    # Count frequencies of each character
    freq = {}
    for ch in s:
        freq[ch] = freq.get(ch, 0) + 1

    # Find the maximum frequency
    max_freq = max(freq.values())

    # Collect characters that appear exactly max_freq times
    chars_with_max_freq = {ch for ch, count in freq.items() if count == max_freq}

    # Build the result by taking the last occurrence of each such character
    result = []
    for ch in reversed(s):
        if ch in chars_with_max_freq:
            result.append(ch)
            chars_with_max_freq.remove(ch)
            if not chars_with_max_freq:
                break

    return ''.join(reversed(result))
```

