def make_smallest_palindrome(s: str) -> str:
    s = list(s)
    n = len(s)

    for i in range(n // 2):
        left, right = s[i], s[n - 1 - i]
        if left != right:
            if left < right:
                s[n - 1 - i] = left
            else:
                s[i] = right

    return ''.join(s)
