Here’s a Python solution that checks all possible placements (including rotations) of the three given polyominoes to see if they can tile the 4×4 grid without overlap or going out of bounds.  
It reads the input from standard input and prints `Yes` or `No`.

```python
import sys
from itertools import product

def rotate(poly):
    """Rotate 4x4 polyomino 90 degrees clockwise."""
    return tuple(tuple(poly[3 - c][r] for c in range(4)) for r in range(4))

def all_rotations(poly):
    """Return all unique rotations of a 4x4 polyomino."""
    rotations = []
    current = poly
    for _ in range(4):
        if current not in rotations:
            rotations.append(current)
        current = rotate(current)
    return rotations

def normalize(poly):
    """Remove empty rows/columns around the polyomino."""
    rows = [r for r in range(4) if any(poly[r][c] == '#' for c in range(4))]
    cols = [c for c in range(4) if any(poly[r][c] == '#' for r in range(4))]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)
    return tuple(tuple(poly[r][c] for c in range(min_c, max_c + 1)) for r in range(min_r, max_r + 1))

def placements(poly):
    """Generate all possible placements of the polyomino on a 4x4 grid."""
    poly = normalize(poly)
    h, w = len(poly), len(poly[0])
    for r in range(4 - h + 1):
        for c in range(4 - w + 1):
            mask = 0
            for i in range(h):
                for j in range(w):
                    if poly[i][j] == '#':
                        mask |= 1 << ((r + i) * 4 + (c + j))
            yield mask

def solve():
    input_data = sys.stdin.read().strip().split()
    polys = []
    for p in range(3):
        poly = tuple(tuple(input_data[p * 16 + r * 4 + c] for c in range(4)) for r in range(4))
        rotations = all_rotations(poly)
        placements_set = set()
        for rot in rotations:
            placements_set.update(placements(rot))
        polys.append(list(placements_set))

    full_mask = (1 << 16) - 1
    for p1, p2, p3 in product(*polys):
        if p1 & p2 == 0 and p1 & p3 == 0 and p2 & p3 == 0:
            if (p1 | p2 | p3) == full_mask:
                print("Yes")
                return
    print("No")

if __name__ == "__main__":
    solve()
```

