def smallestString(s: str) -> str:
    n = len(s)
    chars = list(s)

    # Find the first character that is not 'a'
    start = 0
    while start < n and chars[start] == 'a':
        start += 1

    # If all characters are 'a', change the last one to 'z'
    if start == n:
        chars[-1] = 'z'
        return ''.join(chars)

    # Change characters from start until we hit an 'a' or end of string
    end = start
    while end < n and chars[end] != 'a':
        chars[end] = chr(ord(chars[end]) - 1)
        end += 1

    return ''.join(chars)
