def count_beautiful_numbers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_upto(limit: int) -> int:
        digits = list(map(int, str(limit)))
        n = len(digits)

        @lru_cache(None)
        def dp(pos, tight, even_count, odd_count, rem):
            if pos == n:
                return 1 if even_count == odd_count and rem == 0 else 0

            max_digit = digits[pos] if tight else 9
            total = 0
            for d in range(max_digit + 1):
                new_tight = tight and (d == max_digit)
                new_even = even_count + (1 if (d % 2 == 0 and pos != 0 or d != 0) else 0)
                new_odd = odd_count + (1 if d % 2 == 1 else 0)
                new_rem = (rem * 10 + d) % k
                total += dp(pos + 1, new_tight, new_even, new_odd, new_rem)
            return total

        return dp(0, True, 0, 0, 0)

    return count_upto(high) - count_upto(low - 1)
```

