        for j in range(W):
            color_idx = ord(grid[i][j]) - ord('a')
            row_color_count[i][color_idx] += 1
            col_color_count[j][color_idx] += 1

    queue = deque()

    # Initial check for rows and columns to mark
    for i in range(H):
        if W - row_rem[i] >= 2:
            for c in range(26):
                if row_color_count[i][c] == W - row_rem[i]:
                    queue.append(('row', i))
                    break

    for j in range(W):
        if H - col_rem[j] >= 2:
            for c in range(26):
                if col_color_count[j][c] == H - col_rem[j]:
                    queue.append(('col', j))
