        [(0,0), (1,0), (2,0)],
        [(0,1), (1,1), (2,1)],
        [(0,2), (1,2), (2,2)],
        [(0,0), (1,1), (2,2)],
        [(0,2), (1,1), (2,0)],
    ]

    def check_win(board):
        for line in lines:
            v0 = board[line[0][0]][line[0][1]]
            v1 = board[line[1][0]][line[1][1]]
            v2 = board[line[2][0]][line[2][1]]
            if v0 != 0 and v0 == v1 == v2:
                return v0
        return 0

    memo = {}

    def minimax(board):
        filled = 0
        for i in range(3):
            for j in range(3):
                if board[i][j] != 0:
                    filled += 1

        winner = check_win(board)
        if winner == 1:
            return 1
        if winner == 2:
            return -1

        if filled == 9:
            t_score = 0
            a_score = 0
            for i in range(3):
                for j in range(3):
                    if board[i][j] == 1:
                        t_score += A[i][j]
                    elif board[i][j] == 2:
                        a_score += A[i][j]
            return 1 if t_score > a_score else -1

        state = (tuple(tuple(r) for r in board),)
        if state in memo:
            return memo[state]

        turn = filled % 2  # 0 = Takahashi, 1 = Aoki

        if turn == 0:
            best = -2
            for i in range(3):
                for j in range(3):
                    if board[i][j] == 0:
                        board[i][j] = 1
                        res = minimax(board)
                        board[i][j] = 0
                        if res > best:
                            best = res
                        if best == 1:
                            break
                if best == 1:
                    break
        else:
            best = 2
            for i in range(3):
                for j in range(3):
                    if board[i][j] == 0:
                        board[i][j] = 2
                        res = minimax(board)
                        board[i][j] = 0
                        if res < best:
                            best = res
                        if best == -1:
                            break
                if best == -1:
                    break

        memo[state] = best
        return best

    board = [[0] * 3 for _ in range(3)]
    result = minimax(board)
    if result == 1:
        print("Takahashi")
    else:
        print("Aoki")

