def minChanges(s: str, k: int) -> int:
    n = len(s)
    INF = 10**9

    # Precompute cost[i][j] = min changes to make s[i:j+1] a semi-palindrome
    cost = [[INF] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            best = INF
            for d in range(1, length):
                if length % d != 0:
                    continue
                changes = 0
                for r in range(d):
                    chars = []
                    pos = i + r
                    while pos <= j:
                        chars.append(s[pos])
                        pos += d
                    # Make palindrome
                    lc = 0
                    rc = len(chars) - 1
                    while lc < rc:
                        if chars[lc] != chars[rc]:
                            changes += 1
                        lc += 1
                        rc -= 1
                best = min(best, changes)
            cost[i][j] = best

    # DP: dp[pos][parts] = min cost to split s[pos:] into 'parts' parts
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[n][0] = 0

    for pos in range(n - 1, -1, -1):
        for parts in range(1, k + 1):
            for end in range(pos + 1, n + 1):
                if dp[end][parts - 1] != INF and cost[pos][end - 1] != INF:
                    dp[pos][parts] = min(dp[pos][parts], cost[pos][end - 1] + dp[end][parts - 1])

    return dp[0][k]
```

