def stringIndices(wordsContainer, wordsQuery):
    class TrieNode:
        def __init__(self):
            self.children = {}
            self.best_index = -1

    root = TrieNode()

    def insert_word(word, index):
        node = root
        # Update root best for empty suffix
        if node.best_index == -1:
            node.best_index = index
        else:
            prev_word = wordsContainer[node.best_index]
            curr_word = wordsContainer[index]
            if len(curr_word) < len(prev_word) or (len(curr_word) == len(prev_word) and index < node.best_index):
                node.best_index = index
        for ch in reversed(word):
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            if node.best_index == -1:
                node.best_index = index
            else:
                prev_word = wordsContainer[node.best_index]
                curr_word = wordsContainer[index]
                if len(curr_word) < len(prev_word) or (len(curr_word) == len(prev_word) and index < node.best_index):
                    node.best_index = index

    for i, word in enumerate(wordsContainer):
        insert_word(word, i)

    ans = []
    for query in wordsQuery:
        node = root
        best = node.best_index
        for ch in reversed(query):
            if ch in node.children:
                node = node.children[ch]
                best = node.best_index
            else:
                break
        ans.append(best)
    return ans
