def medianOfUniquenessArray(nums):
    n = len(nums)
    total = n * (n + 1) // 2
    target = (total + 1) // 2  # median position (1-indexed)

    def count_at_most(k):
        count = 0
        freq = {}
        left = 0
        distinct = 0
        for right in range(n):
            freq[nums[right]] = freq.get(nums[right], 0) + 1
            if freq[nums[right]] == 1:
                distinct += 1
            while distinct > k:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
                    distinct -= 1
                left += 1
            count += right - left + 1
        return count

    low, high = 1, len(set(nums))
    ans = low
    while low <= high:
        mid = (low + high) // 2
        if count_at_most(mid) >= target:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1
    return ans
