import sys
from itertools import permutations

def solve():
    data = sys.stdin.read().split()
    idx = 0
    H = int(data[idx]); idx += 1
    W = int(data[idx]); idx += 1

    A = []
    for i in range(H):
        row = []
        for j in range(W):
            row.append(int(data[idx])); idx += 1
        A.append(row)

    B = []
    for i in range(H):
        row = []
        for j in range(W):
            row.append(int(data[idx])); idx += 1
        B.append(row)

    def count_inversions(perm):
        inv = 0
        n = len(perm)
        for i in range(n):
            for j in range(i + 1, n):
                if perm[i] > perm[j]:
                    inv += 1
        return inv

    min_ops = float('inf')

    row_perms = list(permutations(range(H)))
    col_perms = list(permutations(range(W)))

    for rp in row_perms:
        for cp in col_perms:
            match = True
            for i in range(H):
                for j in range(W):
                    if A[rp[i]][cp[j]] != B[i][j]:
                        match = False
                        break
                if not match:
                    break

            if match:
                ops = count_inversions(rp) + count_inversions(cp)
                if ops < min_ops:
                    min_ops = ops

    if min_ops == float('inf'):
        print(-1)
    else:
        print(min_ops)

solve()
