def shortest_superstring(a: str, b: str, c: str) -> str:
    strings = [a, b, c]
    n = len(strings)

    # Precompute overlap[i][j] = max overlap where suffix of i matches prefix of j
    overlap = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            s1, s2 = strings[i], strings[j]
            max_overlap = min(len(s1), len(s2))
            for k in range(max_overlap, 0, -1):
                if s1[-k:] == s2[:k]:
                    overlap[i][j] = k
                    break

    # Merge two strings with maximum overlap
    def merge(s1: str, s2: str, ov: int) -> str:
        return s1 + s2[ov:]

    best = None
    # Try all permutations of the three strings
    import itertools
    for perm in itertools.permutations(range(n)):
        merged = strings[perm[0]]
        for idx in range(1, n):
            ov = overlap[perm[idx - 1]][perm[idx]]
            merged = merge(merged, strings[perm[idx]], ov)
        if best is None or len(merged) < len(best) or (len(merged) == len(best) and merged < best):
            best = merged

    return best
