Looking at this problem, I need to efficiently handle:
1. Range flips on a binary string
2. Range queries checking if a substring is "good" (alternating characters)

**Key Insight:** Define `D[i] = 1` if `S[i] == S[i+1]`, else `0`. A substring `S[L..R]` is good iff `sum(D[L..R-1]) == 0`.

When flipping `S[L..R]`:
- `D[i]` for `L ≤ i ≤ R-1` stays the same (both neighbors flip, equality preserved)
- `D[L-1]` flips (only `S[L]` changes)
- `D[R]` flips (only `S[R]` changes)

So a range flip on S becomes at most **2 point flips** on D, and we just need range sum queries on D — perfect for a Fenwick tree!

```python
import sys

def solve():
    data = sys.stdin.buffer.read().split()
    idx = 0
    N = int(data[idx]); idx += 1
    Q = int(data[idx]); idx += 1
    S = data[idx].decode(); idx += 1

    D = [0] * (N + 1)
    bit = [0] * (N + 1)

    def update(i, delta):
        while i <= N:
            bit[i] += delta
            i += i & (-i)

    def query(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & (-i)
        return s

    def range_query(l, r):
        if l > r:
            return 0
        return query(r) - query(l - 1)

    for i in range(1, N):
        if S[i - 1] == S[i]:
            D[i] = 1
            update(i, 1)

    output = []
    for _ in range(Q):
        t = int(data[idx]); idx += 1
        L = int(data[idx]); idx += 1
        R = int(data[idx]); idx += 1

        if t == 1:
            if L > 1:
                i = L - 1
                if D[i] == 1:
                    D[i] = 0
                    update(i, -1)
                else:
                    D[i] = 1
                    update(i, 1)
            if R < N:
                i = R
                if D[i] == 1:
                    D[i] = 0
                    update(i, -1)
                else:
                    D[i] = 1
                    update(i, 1)
        else:
            if L == R:
                output.append("Yes")
            else:
                bad = range_query(L, R - 1)
                if bad == 0:
                    output.append("Yes")
                else:
                    output.append("No")

    sys.stdout.write('\n'.join(output) + '\n')

solve()
