def maxPalindromesAfterSwaps(words):
    total_chars = 0
    odd_count = 0
    length_counts = {}

    for word in words:
        length_counts[len(word)] = length_counts.get(len(word), 0) + 1
        total_chars += len(word)
        char_count = {}
        for ch in word:
            char_count[ch] = char_count.get(ch, 0) + 1
        for count in char_count.values():
            if count % 2 == 1:
                odd_count += 1

    # Sort lengths to fill smaller words first
    sorted_lengths = sorted(length_counts.keys())

    # We need to see how many words can be made palindrome
    # A word can be palindrome if at most one character has odd frequency
    # We can distribute odd characters among words
    answer = 0
    for length in sorted_lengths:
        count = length_counts[length]
        for _ in range(count):
            # Number of odd slots available for this word
            max_odds = 1 if length % 2 == 1 else 0
            if odd_count >= max_odds:
                odd_count -= max_odds
                answer += 1
            else:
                # If not enough odd characters, check if we can still form palindrome
                if odd_count == 0 and max_odds == 0:
                    answer += 1
                elif odd_count == 0 and max_odds == 1:
                    # Can't make odd-length palindrome without odd character
                    break
    return answer
