However, for large \( N \) (up to \( 2 \times 10^5 \)), the above \( O(N^2) \) approach is too slow.  
We can use a **Fenwick tree (BIT)** to solve it in \( O(N \log N) \):  

```python
import sys

class Fenwick:
    def __init__(self, n):
        self.n = n
        self.bit = [0] * (n + 1)
    def add(self, i, x):
        while i <= self.n:
            self.bit[i] += x
            i += i & -i
    def sum(self, i):
        s = 0
        while i > 0:
            s += self.bit[i]
            i -= i & -i
        return s
    def range_sum(self, l, r):
        return self.sum(r) - self.sum(l - 1)

def solve():
    input = sys.stdin.readline
    N = int(input())
    pairs = []
    for _ in range(N):
        a, b = map(int, input().split())
        if a > b:
            a, b = b, a
        pairs.append((a, b))

    pairs.sort()
    bit = Fenwick(2 * N)

    for a, b in pairs:
        if bit.range_sum(a, b) > 0:
            print("Yes")
            return
        bit.add(b, 1)

    print("No")

if __name__ == "__main__":
    solve()
```

