        idx_v = ord(v) - ord('a')
        if c < dist[idx_u][idx_v]:
            dist[idx_u][idx_v] = c

    # Floyd-Warshall algorithm to find all-pairs shortest paths
    for k in range(26):
        dist_k = dist[k]
        for i in range(26):
            dist_i = dist[i]
            dist_ik = dist_i[k]
            if dist_ik == INF:
                continue
            for j in range(26):
                new_dist = dist_ik + dist_k[j]
                if new_dist < dist_i[j]:
                    dist_i[j] = new_dist

    total_cost = 0
    for s_char, t_char in zip(source, target):
        idx_s = ord(s_char) - ord('a')
        idx_t = ord(t_char) - ord('a')
        if idx_s == idx_t:
            continue
        if dist[idx_s][idx_t] == INF:
            return -1
        total_cost += dist[idx_s][idx_t]

    return total_cost
