def smallestBeautifulSubstring(s: str, k: int) -> str:
    n = len(s)
    min_len = n + 1
    best = ""

    # First pass: find the minimum length among all beautiful substrings
    for i in range(n):
        ones = 0
        for j in range(i, n):
            if s[j] == '1':
                ones += 1
            if ones == k:
                length = j - i + 1
                if length < min_len:
                    min_len = length
                break
            elif ones > k:
                break

    if min_len == n + 1:
        return ""

    # Second pass: find the lexicographically smallest among substrings of min_len
    for i in range(n - min_len + 1):
        sub = s[i:i + min_len]
        if sub.count('1') == k:
            if best == "" or sub < best:
                best = sub

    return best
