```python
import sys

def can_place(grid, H, W, tile_h, tile_w, top_left_r, top_left_c):
    if top_left_r + tile_h > H or top_left_c + tile_w > W:
        return False
    for r in range(top_left_r, top_left_r + tile_h):
        for c in range(top_left_c, top_left_c + tile_w):
            if grid[r][c]:
                return False
    return True

def place_tile(grid, H, W, tile_h, tile_w, top_left_r, top_left_c, val):
    for r in range(top_left_r, top_left_r + tile_h):
        for c in range(top_left_c, top_left_c + tile_w):
            grid[r][c] = val

def backtrack(tiles, idx, grid, H, W):
    if idx == len(tiles):
        for r in range(H):
            for c in range(W):
                if not grid[r][c]:
                    return False
        return True

    # find first empty cell
    first_empty = None
    for r in range(H):
        for c in range(W):
            if not grid[r][c]:
                first_empty = (r, c)
                break
        if first_empty:
            break

    if not first_empty:
        return True  # grid already fully covered

    r, c = first_empty
    h, w = tiles[idx]
    for tile_h, tile_w in [(h, w), (w, h)]:
        if can_place(grid, H, W, tile_h, tile_w, r, c):
            place_tile(grid, H, W, tile_h, tile_w, r, c, 1)
            if backtrack(tiles, idx + 1, grid, H, W):
                return True
            place_tile(grid, H, W, tile_h, tile_w, r, c, 0)
    return False

