        tiles.append((A, B))
        idx += 2

    # sort tiles by area descending for better pruning
    tiles.sort(key=lambda x: x[0]*x[1], reverse=True)
    grid = [[0]*W for _ in range(H)]
    if backtrack(tiles, 0, grid, H, W):
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
