def numberOfPowerfulInt(start: int, finish: int, limit: int, s: str) -> int:
    def count_powerful(upper: int) -> int:
        upper_str = str(upper)
        n = len(upper_str)
        m = len(s)

        if n < m:
            return 0
        if n == m:
            return 1 if upper_str >= s else 0

        prefix_len = n - m
        dp = [[0, 0] for _ in range(prefix_len + 1)]
        dp[0][1] = 1  # tight

        for i in range(prefix_len):
            cur_digit = int(upper_str[i])
            for tight in range(2):
                if dp[i][tight] == 0:
                    continue
                max_digit = cur_digit if tight else limit
                for d in range(max_digit + 1):
                    if d > limit:
                        continue
                    next_tight = tight and (d == cur_digit)
                    dp[i + 1][next_tight] += dp[i][tight]

        total = 0
        for tight in range(2):
            total += dp[prefix_len][tight]

        if upper_str[prefix_len:] >= s:
            total -= dp[prefix_len][1]
        else:
            total -= dp[prefix_len][0] + dp[prefix_len][1]

        return total

    return count_powerful(finish) - count_powerful(start - 1)
