from typing import List
from math import gcd
from collections import defaultdict

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    dsu = DSU(n)
    prime_to_index = {}

    for i, num in enumerate(nums):
        # Find all prime factors of num
        temp = num
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                if d in prime_to_index:
                    dsu.union(i, prime_to_index[d])
                else:
                    prime_to_index[d] = i
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp in prime_to_index:
                dsu.union(i, prime_to_index[temp])
            else:
                prime_to_index[temp] = i

    # Check if all indices are connected
    root = dsu.find(0)
    for i in range(1, n):
        if dsu.find(i) != root:
            return False
    return True
