```python
def numWays(n: int, x: int) -> int:
    MOD = 10**9 + 7

    # Generate all possible x-th powers <= n
    powers = []
    i = 1
    while True:
        power = i ** x
        if power > n:
            break
        powers.append(power)
        i += 1

    # Memoized DFS to count valid combinations
    memo = {}

    def dfs(target, idx):
        if target == 0:
            return 1
        if target < 0 or idx >= len(powers):
            return 0
        state = (target, idx)
        if state in memo:
            return memo[state]

        # Option 1: Include current power
        res = 0
        if powers[idx] <= target:
            res += dfs(target - powers[idx], idx + 1)

        # Option 2: Skip current power
        res += dfs(target, idx + 1)

        res %= MOD
        memo[state] = res
        return res

    return dfs(n, 0)
```

