def permutationDifference(s: str, t: str) -> int:
    # Store the index of each character in s
    char_index_s = {char: i for i, char in enumerate(s)}

    # Calculate the sum of absolute differences between indices
    total_diff = 0
    for i, char in enumerate(t):
