```python
import sys

def solve():
    input_data = sys.stdin.read().strip().split()
    N, H, W = map(int, input_data[:3])
    tiles = []
    idx = 3
    for _ in range(N):
        a, b = int(input_data[idx]), int(input_data[idx+1])
        idx += 2
        tiles.append((a, b))

    grid = [[0]*W for _ in range(H)]
    used = [False]*N

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(r, r+h):
            for j in range(c, c+w):
                if grid[i][j] != 0:
                    return False
        return True

    def place(r, c, h, w, tile_id):
        for i in range(r, r+h):
            for j in range(c, c+w):
                grid[i][j] = tile_id

    def remove(r, c, h, w):
        for i in range(r, r+h):
            for j in range(c, c+w):
                grid[i][j] = 0

    def backtrack():
        # find first empty cell
        for r in range(H):
            for c in range(W):
                if grid[r][c] == 0:
                    for i in range(N):
                        if used[i]:
                            continue
                        a, b = tiles[i]
                        for (h, w) in [(a, b), (b, a)]:
                            if can_place(r, c, h, w):
                                place(r, c, h, w, i+1)
                                used[i] = True
                                if backtrack():
                                    return True
                                used[i] = False
                                remove(r, c, h, w)
                    return False
        return True

    if backtrack():
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    solve()
```

Looking at this problem, I need to determine if a subset of N tiles can exactly cover an H×W grid.

**Key observations:**
- N ≤ 7, so at most 2^7 = 128 subsets to check
- For each subset, the total area must equal H×W
- I can use backtracking: find the first empty cell (topmost-leftmost), which MUST be the top-left corner of some tile placed there (since all cells before it are already filled)
