def can_tile(grid, H, W, tiles, used_mask, target_mask):
    r, c = -1, -1
    for i in range(H):
        for j in range(W):
            if not grid[i][j]:
                r, c = i, j
                break
        if r != -1:
            break

    if r == -1:
        return used_mask == target_mask

    for i in range(len(tiles)):
        if not (target_mask & (1 << i)):
            continue
        if used_mask & (1 << i):
            continue
        a, b = tiles[i]

        orientations = ((a, b), (b, a)) if a != b else ((a, b),)
        for da, db in orientations:
            if r + da <= H and c + db <= W:
                can_place = True
                for di in range(da):
                    for dj in range(db):
                        if grid[r + di][c + dj]:
                            can_place = False
                            break
                    if not can_place:
                        break

                if can_place:
                    for di in range(da):
