def can_traverse_all_pairs(nums):
    n = len(nums)
    if n == 1:
        return True

    max_val = max(nums)

    # Sieve of Eratosthenes to compute Smallest Prime Factor (SPF)
    spf = list(range(max_val + 1))
    for i in range(2, int(max_val**0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_val + 1, i):
                if spf[j] == j:
                    spf[j] = i

    # DSU Initialization
    parent = list(range(n))
    rank = [0] * n

    def find(i):
        root = i
        while parent[root] != root:
            root = parent[root]
        # Path compression
        curr = i
        while curr != root:
            nxt = parent[curr]
            parent[curr] = root
            curr = nxt
        return root

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            if rank[root_i] < rank[root_j]:
                parent[root_i] = root_j
            elif rank[root_i] > rank[root_j]:
                parent[root_j] = root_i
            else:
                parent[root_j] = root_i
                rank[root_i] += 1
            return True
        return False

    prime_to_index = {}

    for i, num in enumerate(nums):
        temp = num
        while temp > 1:
            p = spf[temp]
            while temp % p == 0:
                temp //= p

            if p in prime_to_index:
                union(i, prime_to_index[p])
            else:
                prime_to_index[p] = i

    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
