def get_smallest_string(s: str, k: int) -> str:
    res = []
    for ch in s:
        if k == 0:
            res.append(ch)
            continue

        dist_to_a = min(ord(ch) - ord('a'), ord('z') - ord(ch) + 1)
        if dist_to_a <= k:
            res.append('a')
            k -= dist_to_a
        else:
            # Move towards 'a' but not all the way
            new_char = chr(ord(ch) - k)
            res.append(new_char)
            k = 0
    return ''.join(res)

