def getSmallestString(s: str, k: int) -> str:
    res = []
    for char in s:
        for c in range(26):
            target = ord('a') + c
            diff = abs(ord(char) - target)
            cost = min(diff, 26 - diff)
            if cost <= k:
                res.append(chr(target))
                k -= cost
                break
    return "".join(res)
