def maximumJumps(nums, target):
    n = len(nums)
    # dp[i] represents the maximum number of jumps to reach index i
    # Initialize with -1 to indicate that an index is not reachable
    dp = [-1] * n
    dp[0] = 0  # Starting position requires 0 jumps

    for i in range(1, n):
        for j in range(i):
            # Check if index j is reachable and if jump condition is satisfied
            if dp[j] != -1 and abs(nums[i] - nums[j]) <= target:
                # Update dp[i] if we found a longer path
                if dp[i] == -1 or dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1

    return dp[n - 1]
```

