def min_operations_to_make_equal(s1: str, s2: str, s3: str) -> int:
    # Find the shortest length among the three strings
    min_len = min(len(s1), len(s2), len(s3))

    # Find the longest common prefix length
    common_len = 0
    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            common_len += 1
        else:
            break

    # If no common prefix, impossible to make them equal
    if common_len == 0:
        return -1

    # Total operations = (len(s1) - common_len) + (len(s2) - common_len) + (len(s3) - common_len)
    return (len(s1) - common_len) + (len(s2) - common_len) + (len(s3) - common_len)
